package com.ruoyi.ai.agent;

import com.fasterxml.jackson.databind.node.*;
import junit.framework.TestCase;
import java.lang.reflect.Field;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import static com.ruoyi.ai.agent.AgentJson.*;

public class B8bMergeSaveMysqlTest extends TestCase {
    private A1TestFixture fixture;private ControlledWriteService controlled;private StableEffectLedger effects;
    @Override protected void setUp() throws Exception {
        if(!Boolean.getBoolean("a1.schema.prepared"))throw new IllegalStateException("Prepared isolated B8b schema required");
        fixture=new A1TestFixture();String module=System.getProperty("a1.module");String sql=new String(Files.readAllBytes(Paths.get(module,"sql","ai_agent_controlled_write_v2.sql")),StandardCharsets.UTF_8);fixture.db.execute(sql.replaceAll("(?m)^--[^\\r\\n]*","").trim());
        controlled=new ControlledWriteService(new AgentStore(fixture.db),fixture.guard,fixture.workbooks,fixture.versions,fixture.tx.getTransactionManager());for(String name:new String[]{"enabled","b8EffectEnabled","b8MergeEnabled"}){Field f=ControlledWriteService.class.getDeclaredField(name);f.setAccessible(true);f.set(controlled,true);}effects=new StableEffectLedger(fixture.db);
    }
    private ObjectNode baseline(){return (ObjectNode)parse("{\"id\":\"p\",\"sheetOrder\":[\"s\"],\"sheets\":{\"s\":{\"id\":\"s\",\"name\":\"Sheet\",\"rowCount\":6,\"columnCount\":6,\"cellData\":{\"0\":{\"0\":{\"v\":\"top\",\"t\":1},\"1\":{\"v\":\"loss\",\"t\":1}},\"3\":{\"3\":{\"v\":\"outside\",\"t\":1}}},\"mergeData\":[]}}}");}
    private ObjectNode request(long book,String type,boolean force){ObjectNode ws=fixture.runs.workspace(book,1);ObjectNode req=obj().put("requestId",UUID.randomUUID().toString()).put("workbookId",book).put("branchId",ws.path("branchId").asLong()).put("loadedRevision",ws.path("loadedRevision").asText()).put("expectedDraftVersion",ws.path("draftVersion").asLong()).put("expectedBranchVersion",ws.path("branchVersion").asLong()).put("activeSheetId","s").put("overwrite","confirmed");req.set("writeScopes",arr().add(obj().put("sheetId","s").put("range","A1:B2")));ObjectNode action=obj().put("schemaVersion","2.0").put("type",type);action.set("target",obj().put("sheetId","s").put("range","A1:B2"));if(force)action.put("force",true);req.set("actions",arr().add(action));return req;}
    private ObjectNode claim(ObjectNode run){return controlled.claim(run.path("runId").asText(),1,obj().put("transportVersion",2).put("clientId","b8b-test").put("fencingToken",run.path("fencingToken").asLong()));}
    private ObjectNode receipt(ObjectNode m){ObjectNode r=obj().put("transportVersion",2).put("callId",m.path("callId").asText()).put("effectId",m.path("effectId").asText()).put("claimToken",m.path("claimToken").asText()).put("argsHash",m.path("argsHash").asText()).put("fencingToken",m.path("fencingToken").asLong()).put("ok",true);r.set("mergeReadback",m.path("mergeReadback").deepCopy());return r;}
    private void reject(Runnable r){try{r.run();fail("unsafe merge accepted");}catch(IllegalArgumentException expected){assertNotNull(expected.getMessage());}}
    public void testForcedMergeAndExactBreakApartPersistOnce(){long book=fixture.seed(baseline().toString());reject(()->controlled.create(request(book,"merge",false),1));ObjectNode run=controlled.create(request(book,"merge",true),1),m=claim(run),receipt=receipt(m);assertFalse(m.path("effectId").asText().isEmpty());ObjectNode forged=receipt.deepCopy();((ObjectNode)forged.path("mergeReadback")).put("range","C1:D2");reject(()->controlled.receipt(run.path("runId").asText(),1,forged));assertNull(fixture.status(book).get("workingState"));ObjectNode saved=controlled.receipt(run.path("runId").asText(),1,receipt);assertEquals("COMPLETED",saved.path("status").asText());assertEquals("controlled-merge",saved.path("lastControlledResult").path("executedChange").path("kind").asText());controlled.receipt(run.path("runId").asText(),1,receipt);effects.assertStatus(m.path("effectId").asText(),run.path("runId").asText(),m.path("callId").asText(),"PERSISTED");ObjectNode ws=fixture.runs.workspace(book,1);assertEquals(1,ws.path("snapshot").path("sheets").path("s").path("mergeData").size());assertTrue(ws.path("snapshot").path("sheets").path("s").path("cellData").path("0").path("1").isMissingNode());assertEquals("outside",ws.path("snapshot").path("sheets").path("s").path("cellData").path("3").path("3").path("v").asText());ObjectNode split=controlled.create(request(book,"breakApart",false),1),splitManifest=claim(split),splitReceipt=receipt(splitManifest),done=controlled.receipt(split.path("runId").asText(),1,splitReceipt);assertEquals("COMPLETED",done.path("status").asText());assertEquals(0,fixture.runs.workspace(book,1).path("snapshot").path("sheets").path("s").path("mergeData").size());assertEquals(2,fixture.db.queryForObject("select count(*) from ai_agent_effect where status='PERSISTED' and run_id in (?,?)",Integer.class,run.path("runId").asText(),split.path("runId").asText()).intValue());}
    public void testFailedExecutionBecomesUnknownWithoutSave(){long book=fixture.seed(baseline().toString());ObjectNode run=controlled.create(request(book,"merge",true),1),m=claim(run),failed=receipt(m);failed.remove("mergeReadback");failed.put("ok",false).put("error","disconnected after SDK call");ObjectNode unknown=controlled.receipt(run.path("runId").asText(),1,failed);assertEquals("PAUSED",unknown.path("status").asText());assertNull(fixture.status(book).get("workingState"));effects.assertStatus(m.path("effectId").asText(),run.path("runId").asText(),m.path("callId").asText(),"UNKNOWN");reject(()->controlled.receipt(run.path("runId").asText(),1,receipt(m)));}
}
